// Setup memory region (e.g., page-aligned)
const size_t LEN = 4096;
void* mem = mmap(NULL, LEN, PROT_NONE,
                 MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);

// 1. Allocate a protection key
int pkey = pkey_alloc(0, 0); // No flags, default permissions

// 2. Define desired protection
int prot = PROT_READ | PROT_WRITE;

// 3. Apply protection and assign key 'pkey' to memory region
long ret = pkey_mprotect(mem, LEN, prot, pkey);

// Cleanup
pkey_free(pkey);
munmap(mem, LEN);
